from flask import Flask, redirect, request, abort
from urllib.parse import urlparse

app = Flask(__name__)

VALID_DOMAINS = ['example.com', 'example.org']

def is_valid_domain(url):
    parsed_url = urlparse(url)
    return parsed_url.netloc in VALID_DOMAINS

@app.route('/redirect')
def redirectToTarget():
    target_url = request.args.get('url')
    if target_url and is_valid_domain(target_url):
        return redirect(target_url)
    else:
        abort(400)

import os
from flask import Flask, request, abort

app = Flask(__name__)

@app.route('/deleteImage', methods=['DELETE'])
def deleteImage():
    filename = request.args.get('filename')
    if not filename or '..' in filename or filename.startswith('/'):
        abort(400)
    file_path = os.path.join('images_directory', filename)
    try:
        if os.path.exists(file_path):
            os.remove(file_path)
            return {'message': 'File deleted successfully'}, 200
        else:
            return {'message': 'File not found'}, 404
    except Exception as e:
        return {'message': 'Error deleting file', 'error': str(e)}, 500

