from flask import Flask, request, jsonify, send_file
import os

app = Flask(__name__)

@app.route("/filedata")
def getFileData():
    filename = request.args.get('filename')
    if not filename or '..' in filename or filename.startswith('/'):
        return jsonify({"error": "Invalid file name"}), 400

    secure_directory = '/path/to/secure/directory'
    file_path = os.path.join(secure_directory, filename)

    if not os.path.isfile(file_path):
        return jsonify({"error": "File not found"}), 404

    return send_file(file_path)

import tarfile
import os

def extract_tar(file_name):
    if not tarfile.is_tarfile(file_name):
        raise ValueError("Not a valid tar file")

    with tarfile.open(file_name, 'r:*') as tar:
        for member in tar.getmembers():
            if member.isfile():
                extracted_path = os.path.join('/tmp/', member.name)
                # Prevent directory traversal attacks
                if os.path.commonprefix([extracted_path, '/tmp/']) != '/tmp/':
                    raise ValueError("Potential directory traversal attack detected")
                tar.extract(member, path='/tmp/')
